//! Lane C scheduling (ADR-019 `ECA-03`). Reports are generated by
//! `creg-agent-runner` (Zone 4), never in the consensus process: the node
//! sends the committed record over authenticated `zone-ipc`, checks that the
//! report describes that record, and stores it.

use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::Duration;

use anyhow::{bail, Context};
use common::{ChainRecord, IntelligenceStatus, PackageIntelligenceReport};
use tokio::sync::Semaphore;
use tracing::{info, warn};
use zone_ipc::{
    ZoneEndpoint, ZoneId, ZoneIpcClient, ZoneIpcToken, ZoneRequest, ZoneResponse,
    ZONE_IPC_TOKEN_ENV,
};

use super::IntelligenceStore;

static INTELLIGENCE_SEMAPHORE: Semaphore = Semaphore::const_new(2);
static NEXT_REQUEST_ID: AtomicU64 = AtomicU64::new(1);

/// Agent-runner endpoint (same variable and default as the supervisor).
pub const AGENT_IPC_ADDR_ENV: &str = "CREG_AGENT_IPC_ADDR";
const DEFAULT_AGENT_IPC_ADDR: &str = "127.0.0.1:19004";
/// Upper bound on one report: tarball fetch plus the LLM run in Zone 4.
pub const AGENT_REPORT_TIMEOUT: Duration = Duration::from_secs(900);

pub fn intelligence_enabled() -> bool {
    std::env::var("CREG_INTELLIGENCE_ENABLED")
        .map(|v| v == "1" || v.eq_ignore_ascii_case("true"))
        .unwrap_or(false)
}

pub fn intelligence_auto_enabled() -> bool {
    std::env::var("CREG_INTELLIGENCE_AUTO")
        .map(|v| v == "1" || v.eq_ignore_ascii_case("true"))
        .unwrap_or(true)
}

pub fn schedule_for_block(block: &common::Block, data_dir: PathBuf) {
    if !intelligence_enabled() || !intelligence_auto_enabled() {
        return;
    }

    for tx in &block.transactions {
        let Some(record) = tx.published_record() else {
            continue;
        };
        if !matches!(record.status, common::PackageStatus::Verified) {
            continue;
        }
        let record = record.clone();
        let data_dir = data_dir.clone();
        tokio::spawn(async move {
            let Ok(_permit) = INTELLIGENCE_SEMAPHORE.acquire().await else {
                return;
            };
            if let Err(error) = generate_and_store(&record, &data_dir).await {
                warn!(
                    "{} intelligence generation failed: {:#}",
                    record.id.canonical(),
                    error
                );
            }
        });
    }
}

pub async fn generate_and_store(
    record: &ChainRecord,
    data_dir: &std::path::Path,
) -> anyhow::Result<PackageIntelligenceReport> {
    let store = IntelligenceStore::new(data_dir);
    let canonical = record.id.canonical();

    if let Some(existing) = store.get_by_content_hash(&record.content_hash) {
        if matches!(
            existing.status,
            IntelligenceStatus::Ready | IntelligenceStatus::Degraded
        ) {
            info!("{} intelligence cache hit", canonical);
            return Ok(existing);
        }
    }

    let pending = PackageIntelligenceReport::pending(&canonical, &record.content_hash);
    let _ = store.put(&pending);

    let client = agent_runner_client()?;
    let report = request_report(&client, record).await?;
    store.put(&report)?;
    info!(
        "{} intelligence report stored (status={:?})",
        canonical, report.status
    );
    Ok(report)
}

/// Client for Zone 4 from `CREG_AGENT_IPC_ADDR` and `CREG_ZONE_IPC_TOKEN`.
pub fn agent_runner_client() -> anyhow::Result<ZoneIpcClient> {
    let token = ZoneIpcToken::from_env(ZONE_IPC_TOKEN_ENV)
        .context("Lane C needs CREG_ZONE_IPC_TOKEN to reach creg-agent-runner")?;
    let addr = std::env::var(AGENT_IPC_ADDR_ENV)
        .ok()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| DEFAULT_AGENT_IPC_ADDR.to_string());
    let endpoint = ZoneEndpoint::parse(&addr)?;
    Ok(ZoneIpcClient::new(
        ZoneId::Consensus,
        ZoneId::AgentRunner,
        endpoint,
        token,
    ))
}

/// Ask Zone 4 for a report on `record` and accept it only when it describes
/// that exact record.
pub async fn request_report(
    client: &ZoneIpcClient,
    record: &ChainRecord,
) -> anyhow::Result<PackageIntelligenceReport> {
    let request = ZoneRequest::GenerateIntelligenceReport {
        record_json: serde_json::to_string(record).context("serialize ChainRecord")?,
    };
    let request_id = NEXT_REQUEST_ID.fetch_add(1, Ordering::Relaxed);
    let response = tokio::time::timeout(AGENT_REPORT_TIMEOUT, client.call(request_id, &request))
        .await
        .context("creg-agent-runner did not answer within the Lane C timeout")??;
    let report: PackageIntelligenceReport = match response {
        ZoneResponse::IntelligenceReportResult { report_json } => {
            serde_json::from_str(&report_json).context("decode PackageIntelligenceReport")?
        }
        ZoneResponse::Error { code, message } => {
            bail!("creg-agent-runner refused the report ({code}): {message}")
        }
        other => bail!("unexpected creg-agent-runner response: {other:?}"),
    };
    if report.canonical != record.id.canonical()
        || !report
            .content_hash
            .eq_ignore_ascii_case(record.content_hash.trim())
    {
        bail!("creg-agent-runner returned a report for another package");
    }
    Ok(report)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::net::SocketAddr;
    use zone_ipc::ZoneIpcServer;

    async fn agent_stub(answer: fn(&ChainRecord) -> ZoneResponse) -> ZoneIpcClient {
        let token = ZoneIpcToken::generate();
        let addr: SocketAddr = "127.0.0.1:0".parse().expect("addr");
        let server =
            ZoneIpcServer::bind(ZoneId::AgentRunner, ZoneEndpoint::Tcp(addr), token.clone())
                .await
                .expect("bind");
        let endpoint = server.local_endpoint().expect("endpoint");
        tokio::spawn(server.serve(move |sender, request| {
            Box::pin(async move {
                assert_eq!(sender, ZoneId::Consensus);
                match request {
                    ZoneRequest::GenerateIntelligenceReport { record_json } => {
                        let record: ChainRecord =
                            serde_json::from_str(&record_json).expect("record");
                        answer(&record)
                    }
                    _ => ZoneResponse::Error {
                        code: 400,
                        message: "unexpected op".into(),
                    },
                }
            })
        }));
        ZoneIpcClient::new(ZoneId::Consensus, ZoneId::AgentRunner, endpoint, token)
    }

    fn record() -> ChainRecord {
        ChainRecord {
            id: common::PackageId::new("npm", "lane-c", "1.0.0"),
            content_hash: "ab".repeat(32),
            ..ChainRecord::default()
        }
    }

    fn ready_report(record: &ChainRecord) -> ZoneResponse {
        let mut report =
            PackageIntelligenceReport::pending(record.id.canonical(), &record.content_hash);
        report.status = IntelligenceStatus::Ready;
        ZoneResponse::IntelligenceReportResult {
            report_json: serde_json::to_string(&report).expect("report"),
        }
    }

    fn foreign_report(_: &ChainRecord) -> ZoneResponse {
        let report = PackageIntelligenceReport::pending("npm:other@9.9.9", "cd".repeat(32));
        ZoneResponse::IntelligenceReportResult {
            report_json: serde_json::to_string(&report).expect("report"),
        }
    }

    fn refused(_: &ChainRecord) -> ZoneResponse {
        ZoneResponse::Error {
            code: 502,
            message: "CREG_IPFS_URL is not set".into(),
        }
    }

    #[tokio::test]
    async fn reports_come_from_zone_four_and_must_match_the_record() {
        let client = agent_stub(ready_report).await;
        let report = request_report(&client, &record()).await.expect("report");
        assert_eq!(report.canonical, "npm:lane-c@1.0.0");
        assert!(matches!(report.status, IntelligenceStatus::Ready));

        let client = agent_stub(foreign_report).await;
        let error = request_report(&client, &record()).await.unwrap_err();
        assert!(
            format!("{error:#}").contains("another package"),
            "{error:#}"
        );

        let client = agent_stub(refused).await;
        let error = request_report(&client, &record()).await.unwrap_err();
        assert!(format!("{error:#}").contains("502"), "{error:#}");
    }
}
